import static org.mockito.Mockito.when;

@RunWith(PowerMockRunner.class)
@PrepareForTest(Normalize.class)
public class Normalize_visit_TriageGen0Test {

    private Normalize normalize;

    @Mock
    private NodeTraversal mockTraversal;

    @Mock
    private Node mockParent;

    @Mock
    private ErrorReporter mockErrorReporter;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        normalize = new Normalize(mockErrorReporter);
    }

    @Test
    public void testVisit_WhileNodeWithConversionEnabled() {
        // We need to manipulate the static/field CONVERT_WHILE_TO_FOR. 
        // Since it's likely a private static boolean in the real class, 
        // in a real scenario we'd use reflection or a test-only setter if available.
        // Assuming for this test we can control the behavior.

        // Setup Node: WHILE -> Expression
        Node n = new Node(Token.WHILE);
        Node expr = new Node(Token.EXPRESSION);
        n.addChild(expr);

        // We assume CONVERT_WHILE_TO_FOR is true for this test case
        // If it's a field, we use reflection to set it true.
        setConvertWhileToFor(true);

        normalize.visit(mockTraversal, n, mockParent);

        // Verify Node type changed to FOR
        assertEquals(Token.FOR, n.getType());

        // Verify structure: FOR -> EMPTY -> expr -> EMPTY
        // Total children should be 3: [EMPTY, expr, EMPTY]
        assertEquals(3, n.getChildCount());
        assertEquals(Token.EMPTY, n.getFirstChild().getType());
        assertEquals(Token.EXPRESSION, n.getSecondChild().getType());
        assertEquals(Token.EMPTY, n.getLastChild().getType());
    }

    @Test
    public void testVisit_WhileNodeWithConversionDisabled() {
        setConvertWhileToFor(false);

        Node n = new Node(Token.WHILE);
        Node expr = new Node(Token.EXPRESSION);
        n.addChild(expr);

        normalize.visit(mockTraversal, n, mockParent);

        // Verify Node type remains WHILE
        assertEquals(Token.WHILE, n.getType());
        assertEquals(1, n.getChildCount());
    }

    @Test
    public void testVisit_OtherNodeType() {
        setConvertWhileToFor(true);

        Node n = new Node(Token.VAR);
        Node expr = new Node(Token.STRING);
        n.addChild(expr);

        normalize.visit(mockTraversal, n, mockParent);

        // Verify no changes occurred
        assertEquals(Token.VAR, n.getType());
        assertEquals(1, n.getChildCount());
    }

    /**
     * Helper to access the private static field via reflection.
     */
    private void setConvertWhileToFor(boolean value) {
        try {
            java.lang.reflect.Field field = Normalize.class.getDeclaredField("CONVERT_WHILE_TO_FOR");
            field.setAccessible(true);
            field.set(null, value);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
